#include <bits/stdc++.h>
using namespace std;

long long powerMod(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    int L, R;
    cin >> n >> m >> L >> R;

    long long MOD = 998244353;
    long long inv2 = powerMod(2, MOD - 2, MOD);
    long long diff = R - L + 1;
    long long p1 = diff / 2;
    long long p2 = diff - p1;
    long long result;

    if ((n * m) % 2 == 1) {
        result = powerMod(diff, n * m, MOD);
    } else {
        long long totalP1 = diff;
        long long totalP2 = abs(p1 - p2);
        long long opt1 = powerMod(totalP1, n * m, MOD);
        long long opt2 = powerMod(totalP2, n * m, MOD);
        long long sumOpts = (opt1 + opt2) % MOD;
        result = (sumOpts * inv2) % MOD;
    }

    cout << result << "\n";

    return 0;
}
